-- 0.6.0 ADDITIVE migration: administrator inventory adjustments for nonserialized lot groups.
-- Run in the EXISTING D1 Console BEFORE deploying 0.6.0 code. Run each statement once, in order.
-- Nothing here deletes or rewrites existing inventory, events or lot_events.
CREATE TABLE IF NOT EXISTS lot_adjustments (seq INTEGER PRIMARY KEY AUTOINCREMENT, gtin TEXT NOT NULL CHECK(length(gtin)=14), lot TEXT NOT NULL CHECK(length(lot) BETWEEN 1 AND 20), expiration TEXT NOT NULL, product_abc TEXT NOT NULL REFERENCES products(abc), bucket TEXT NOT NULL CHECK(bucket IN('IN_STOCK','OUT')), delta INTEGER NOT NULL CHECK(delta<>0 AND delta BETWEEN -1000 AND 1000), reason TEXT NOT NULL CHECK(length(reason) BETWEEN 8 AND 500), actor TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE INDEX IF NOT EXISTS lot_adjustments_group ON lot_adjustments(gtin,lot,expiration,bucket);
-- Execute each complete CREATE TRIGGER / DROP TRIGGER below as ONE statement (one line each).
CREATE TRIGGER IF NOT EXISTS lot_adjustments_validate BEFORE INSERT ON lot_adjustments BEGIN SELECT RAISE(ABORT,'No such lot group') WHERE NOT EXISTS(SELECT 1 FROM lot_events WHERE gtin=NEW.gtin AND lot=NEW.lot AND expiration=NEW.expiration); SELECT RAISE(ABORT,'Adjustment product conflicts with the lot group') WHERE EXISTS(SELECT 1 FROM lot_events WHERE gtin=NEW.gtin AND lot=NEW.lot AND expiration=NEW.expiration AND product_abc<>NEW.product_abc); SELECT RAISE(ABORT,'Adjustment would make the In stock quantity negative') WHERE NEW.bucket='IN_STOCK' AND COALESCE((SELECT SUM(CASE WHEN action='PULL' THEN -1 ELSE 1 END) FROM lot_events WHERE gtin=NEW.gtin AND lot=NEW.lot AND expiration=NEW.expiration),0)+COALESCE((SELECT SUM(delta) FROM lot_adjustments WHERE gtin=NEW.gtin AND lot=NEW.lot AND expiration=NEW.expiration AND bucket='IN_STOCK'),0)+NEW.delta<0; SELECT RAISE(ABORT,'Adjustment would make the Out quantity negative') WHERE NEW.bucket='OUT' AND COALESCE((SELECT SUM(CASE WHEN action='PULL' THEN 1 WHEN action='RETURN' THEN -1 ELSE 0 END) FROM lot_events WHERE gtin=NEW.gtin AND lot=NEW.lot AND expiration=NEW.expiration),0)+COALESCE((SELECT SUM(delta) FROM lot_adjustments WHERE gtin=NEW.gtin AND lot=NEW.lot AND expiration=NEW.expiration AND bucket='OUT'),0)+NEW.delta<0; END;
CREATE TRIGGER IF NOT EXISTS lot_adjustments_no_update BEFORE UPDATE ON lot_adjustments BEGIN SELECT RAISE(ABORT,'Adjustments are append-only'); END;
CREATE TRIGGER IF NOT EXISTS lot_adjustments_no_delete BEFORE DELETE ON lot_adjustments BEGIN SELECT RAISE(ABORT,'Adjustments are append-only'); END;
-- Pull/Return checks must see adjusted quantities. Create the new rule first, then drop the old one, so there is never a gap.
CREATE TRIGGER IF NOT EXISTS lot_events_validate_v2 BEFORE INSERT ON lot_events BEGIN SELECT RAISE(ABORT,'No matching vial is In stock') WHERE NEW.action='PULL' AND COALESCE((SELECT SUM(CASE WHEN action='PULL' THEN -1 ELSE 1 END) FROM lot_events WHERE gtin=NEW.gtin AND lot=NEW.lot AND expiration=NEW.expiration),0)+COALESCE((SELECT SUM(delta) FROM lot_adjustments WHERE gtin=NEW.gtin AND lot=NEW.lot AND expiration=NEW.expiration AND bucket='IN_STOCK'),0)<1; SELECT RAISE(ABORT,'No matching pulled vial is available to Return') WHERE NEW.action='RETURN' AND COALESCE((SELECT SUM(CASE WHEN action='PULL' THEN 1 WHEN action='RETURN' THEN -1 ELSE 0 END) FROM lot_events WHERE gtin=NEW.gtin AND lot=NEW.lot AND expiration=NEW.expiration),0)+COALESCE((SELECT SUM(delta) FROM lot_adjustments WHERE gtin=NEW.gtin AND lot=NEW.lot AND expiration=NEW.expiration AND bucket='OUT'),0)<1; SELECT RAISE(ABORT,'Lot group product association conflicts with its history') WHERE EXISTS(SELECT 1 FROM lot_events WHERE gtin=NEW.gtin AND lot=NEW.lot AND expiration=NEW.expiration AND (product_abc<>NEW.product_abc OR supplier_ndc11<>NEW.supplier_ndc11 OR scanned_ndc11 IS NOT NEW.scanned_ndc11)); END;
DROP TRIGGER IF EXISTS lot_events_validate;
-- Verify afterwards: SELECT name FROM sqlite_master WHERE type='trigger' AND (name LIKE 'lot_events_validate%' OR name LIKE 'lot_adjustments%');
-- Expected: lot_adjustments_validate, lot_adjustments_no_update, lot_adjustments_no_delete, lot_events_validate_v2 (and NOT lot_events_validate).
